from taf.rfrl.procedures.resources.python.OAM_KPI.GenericKPIMultiBTSEx import GenericKPIMultiBTSEx
from taf.rfrl.procedures.resources.python.OAM_KPI.GenericRunnerKPI import GenericRunnerKPI
from taf.rfrl.utilities.robot.RobotKWRunner import run_as_robot_kw as convert_to_robot_kw


class GenericRunnerKPIMultiBTS(GenericKPIMultiBTSEx, GenericRunnerKPI):

    def __init__(self, operation_description, kpi_names, multi_bts_dict, bts_id=0, du_id=0,
                 additional_allowed_alarms=None, temp_allowed_alarms=None, critical_alarms=None,
                 temp_critical_alarms=None, report_to_rep=True, enable_listener=True, add_default_logs=True, **kwargs):
        self.multi_bts_dict = multi_bts_dict
        super(GenericRunnerKPIMultiBTS, self).__init__(operation_description, kpi_names, bts_id, du_id,
                                                       additional_allowed_alarms, temp_allowed_alarms, critical_alarms,
                                                       temp_critical_alarms, report_to_rep, enable_listener,
                                                       add_default_logs, **kwargs)
        if "dict" in str(type(self.multi_bts_dict)):
            convert_to_robot_kw(self.create_other_bts_objects)

    def create_other_bts_objects(self):
        super(GenericRunnerKPIMultiBTS, self).create_other_bts_objects()
        self._add_target_to_results = \
            self.multi_bts_decorator(self._add_target_to_results)
